import {createStudioProject,normalizeStudioProject,makePart,addConnection,partTransforms,transformPoint,applyStudioProposal,validateStudio,projectBounds,unitsPerMm} from './studio-model.mjs';
import {renderStudioSvg,exportSheetSvg,exportPrintHtml,getFabricationMetrics} from './studio-render.mjs';
import {clearStoredStudioSession,serializeStudioProject,parseStudioProject,readArtworkFile} from './studio-storage.mjs';
import {requestStudioAI,getStudioCapabilities} from './studio-ai.mjs';
import {createStarter} from './studio-starters.mjs';
import {resizePart,setPartParameterAxis,getPartParameters,preservePhysicalScale} from './studio-parametric.mjs';
import {removeConnectedBackground,selectImageRegion,extractImageSilhouette,decodeArtwork,assetFromImageData} from './studio-image-tools.mjs';
import {splitPart,suggestConnection} from './studio-construction.mjs';
import {zoomViewBox,normalizeCamera,panCamera,screenUnitScale} from './studio-viewport.mjs';
import {captureUIState,restoreUIState} from './studio-ui-state.mjs';

const root=document.querySelector('#app');
const state={project:createStudioProject(),step:'create',selected:null,mode:'select',points:[],jointStart:null,jointType:'pivot',showArt:true,showJoints:true,showConcept:true,undo:[],redo:[],proposal:null,proposalBase:null,proposalLabel:'',proposalAfter:null,proposalVersion:null,reply:'',messages:[],prompt:'',revisionPrompt:'',busy:false,capabilities:null,saveStatus:'session',error:'',notice:'',help:false,settings:false,endpoint:'',version:0,imageTolerance:30,imageRaster:null,imageRasterId:null,connectParent:'',refineStage:'clean',reviewView:'after',camera:{zoom:1,x:0,y:0},vertexIndex:null};
let controller,drag=null,lastReview=null,suppressCanvasClick=false,imageOperation=null,sessionEpoch=0,resettingSession=false;
export function getSessionSnapshot(){return structuredClone(state.project);}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(en,zh)=>state.project.language==='zh'?zh:en;
const selected=()=>state.project.parts.find(p=>p.id===state.selected);
const uid=()=>globalThis.crypto?.randomUUID?.()||'p-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const btn=(label,action,cls='',disabled=false,extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${disabled?'disabled':''} ${extra}>${label}</button>`;
const field=(label,content)=>`<label class="field"><span>${label}</span>${content}</label>`;
function selectField(key,label,options,value,attrs=''){return field(label,`<select data-field="${key}" ${attrs}>${options.map(([v,en,zh])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t(en,zh||en))}</option>`).join('')}</select>`);}
function status(){const el=document.querySelector('#save-status');if(el)el.textContent=state.saveStatus==='downloaded'?t('Downloaded · this session only','已下载 · 仅本次会话'):t('This session only · download to keep','仅本次会话 · 请下载保存');}

function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),4500);}
function sessionChanged(){state.saveStatus='session';status();}

function commit(next,label=t('Edit','编辑')){const normalized=normalizeStudioProject(next);const before=partTransforms(state.project),after=partTransforms(normalized);for(const part of state.project.parts.filter(p=>p.locked)){const other=normalized.parts.find(p=>p.id===part.id);if(other?.locked&&(JSON.stringify(part)!==JSON.stringify(other)||before[part.id].some((n,i)=>Math.abs(n-after[part.id][i])>.001)))throw Error(t('This would change a locked part. Unlock it first.','此修改会影响已锁定部件，请先解锁。'));}state.undo.push(state.project);if(state.undo.length>16)state.undo.shift();state.redo=[];state.project=normalized;state.project.revisions=[...(state.project.revisions||[]).slice(-19),{id:uid(),createdAt:new Date().toISOString(),label}];state.version++;state.proposal=null;state.error='';state.notice='';if(!state.project.parts.some(p=>p.id===state.selected))state.selected=null;sessionChanged();render();}
function mutate(fn,label,{keepScale=true}={}){let next=structuredClone(state.project);fn(next);if(keepScale&&(state.project.parts.length||next.parts.length))next=preservePhysicalScale(state.project,next);commit(next,label);}
function resetTool(){state.mode='select';state.points=[];state.jointStart=null;}
function choosePart(id){if(!state.project.parts.some(p=>p.id===id))return;if(!['joint','rod'].includes(state.mode))resetTool();state.connectParent='';state.selected=id;render();}
function download(name,contents,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([contents],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function safeName(){return (state.project.title.trim()||'shadow-puppet').replace(/[^\p{L}\p{N}_-]+/gu,'-').slice(0,60);}
function beginTool(mode){resetTool();state.mode=mode;if(mode==='joint'||mode==='rod')state.selected=null;state.step='refine';if(mode==='draw'||mode==='region')state.refineStage='pieces';else if(mode==='joint'||mode==='rod')state.refineStage='movement';render();}

function conceptAsset(){return state.project.assets.find(a=>a.id===state.project.conceptAssetId);}
function proposeLocal(project,label,reply,after={}){state.proposal=normalizeStudioProject(project);state.proposalBase=structuredClone(state.project);state.proposalLabel=label;state.proposalAfter=after;state.reviewView='after';state.proposalVersion=state.version;state.reply=reply;state.error='';render();}
async function currentRaster(){const epoch=sessionEpoch,asset=conceptAsset();if(!asset)throw Error(t('Import an artwork image first.','请先导入作品图片。'));if(state.imageRasterId!==asset.id){const data=await decodeArtwork(asset);if(epoch!==sessionEpoch||conceptAsset()?.id!==asset.id)throw Error(t('The source image changed. Try again.','原图已更改，请重试。'));state.imageRaster=data;state.imageRasterId=asset.id;}return state.imageRaster;}
function imageToolsPanel(){const asset=conceptAsset();if(!asset)return `<p class="connection-note">${t('Import an image, or draw your own pieces.','导入图片，或绘制自定义部件。')}</p>${btn(t('Import artwork','导入图片'),'import-art','secondary full')}`;return `<section class="image-tools"><h3>${state.refineStage==='clean'?t('Keep the character','保留角色'):t('Choose editable pieces','选择可编辑部件')}</h3><p>${state.refineStage==='clean'?t('Remove a plain background, then review what remains. Skip this if your image is already transparent.','去除纯色背景并检查结果。透明图片可跳过此步。'):t('Find connected silhouettes, or trace one piece at a time. Split connected limbs where you want movement.','提取相连轮廓，或逐个描绘部件。在需要活动的位置分割。')}</p>${state.project.assets.length>1?field(t('Source image','原始图片'),`<select data-source-art>${state.project.assets.map(a=>`<option value="${esc(a.id)}" ${a.id===asset.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select>`):''}${field(t('Selection tolerance','选取容差'),`<input type="range" data-image-tolerance min="0" max="100" step="1" value="${state.imageTolerance}" aria-label="${t('Selection tolerance','选取容差')}"><output id="tolerance-output">${state.imageTolerance}</output>`)}<div class="tool-stack">${state.refineStage==='clean'?btn(t('Remove plain background','去除纯色背景'),'remove-background','secondary',state.busy):`${btn(t('Find silhouette pieces','提取轮廓部件'),'extract-silhouette','secondary',state.busy)}${btn(t('Select a color region','选取颜色区域'),'select-region',state.mode==='region'?'tool active':'tool',state.busy)}`}</div><p class="fine-print">${t('These tools follow pixels. You choose the body parts and joints.','这些工具根据像素选取。部件和关节由你决定。')}</p></section>`;}

function dimensionControls(part){const info=getPartParameters(state.project,part.id);return `<section class="dimension-controls"><h3>${t('Shape & proportions','形状与比例')}</h3>${[['width','Width','宽度'],['length','Length','长度']].map(([key,en,zh])=>field(t(en,zh)+` <output id="parameter-${key}-output">${Math.round(info[key]*100)}%</output>`,`<input type="range" data-param-field="${key}" min="25" max="400" step="1" value="${Math.round(info[key]*100)}" ${part.locked?'disabled':''}>`)).join('')}<div class="dimension-readout">${Number(info.widthMm).toFixed(1)} × ${Number(info.lengthMm).toFixed(1)} mm</div><details class="advanced-controls"><summary>${t('Direction & deformation','方向与变形')}</summary><p>${t('Artwork stretches with its outline. Attached pieces follow their joints.','图案随轮廓变形，相连部件随关节移动。')}</p>${field(t('Length direction · degrees','长度方向 · 度'),`<input type="number" data-param-axis min="-180" max="180" step="1" value="${Math.round(info.axisAngle)}" ${part.locked?'disabled':''}>`)}<p>${t('0° = vertical; 90° = horizontal.','0° 为竖直方向，90° 为水平方向。')}</p>${btn(t('Set direction on the piece','在部件上设置方向'),'parameter-axis','secondary full',part.locked)}<p class="fine-print">${t('Changing direction keeps the current shape and starts new percentages at 100%.','更改方向保留当前形状，并将新的比例设为 100%。')}</p></details></section>`;}

function connectionSuggestion(part){if(state.project.joints.some(j=>j.childId===part.id)||state.project.parts.length<2)return '';const parents=state.project.parts.filter(p=>p.id!==part.id&&!p.locked);return `<details class="connection-suggestion"><summary>${t('Suggest a pivot connection','建议旋转连接')}</summary><p>${t('Choose the piece this part should attach to. A nearby pivot will be proposed for review.','选择此部件要连接的父部件，系统将建议附近的转轴位置供你审核。')}</p><select data-connect-parent aria-label="${t('Parent part','父部件')}"><option value="">${t('Choose parent part','选择父部件')}</option>${parents.map(p=>`<option value="${esc(p.id)}" ${state.connectParent===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>${btn(t('Suggest connection','建议连接'),'suggest-connection','secondary full',part.locked||!parents.some(p=>p.id===state.connectParent))}</details>`;}
async function runImageTool(action,seed){if(state.busy)return;const operation={};imageOperation=operation;state.busy=true;state.error='';const version=state.version;render();try{const asset=conceptAsset(),raster=await currentRaster();if(imageOperation!==operation)return;if(version!==state.version)throw Error(t('The project changed. Try this image action again.','项目已改变，请重新操作。'));let next=structuredClone(state.project),reply='',after={showConcept:true,imageReview:true};
if(action==='remove-background'){const result=removeConnectedBackground(raster,{tolerance:state.imageTolerance});if(!result.removedPixels)throw Error(t('No connected plain background was found. Try a different tolerance, select a region, or trace the outline.','未找到连通的纯色背景。请调整容差、选择区域或手动描绘轮廓。'));const cleaned=await assetFromImageData(result,{name:asset.name+' '+t('(background removed)','（已去除背景）')});if(imageOperation!==operation)return;if(version!==state.version)throw Error(t('The project changed. Try again.','项目已改变，请重试。'));next.assets.push(cleaned);next.conceptAssetId=cleaned.id;for(const p of next.parts)if(p.assetId===asset.id&&!p.locked)p.assetId=cleaned.id;reply=t('Review the transparent areas. Only background connected to the image edge was removed; connected white clothing can also be affected. Your original image is kept.','请检查透明区域。处理仅去除与图像边缘相连的背景，但相连的白色服装也可能受影响。已保留原图。')+' '+(result.warnings||[]).join(' ');}
else{const result=action==='select-region'?selectImageRegion(raster,seed,{tolerance:state.imageTolerance}):extractImageSilhouette(raster,{minArea:Math.max(16,Math.round(raster.width*raster.height*.00005)),maxParts:40});const regions=action==='select-region'?[result]:result.parts;if(!regions.length)throw Error((result.warnings||[]).join(' ')||t('No usable region was found. Trace the outline manually.','未找到可用区域，请手动描绘轮廓。'));if(action==='extract-silhouette'&&regions.length===1&&regions[0].pixelCount>raster.width*raster.height*.97)throw Error(t('The image still has an opaque background. Remove the background first, or select a color region.','图像仍有不透明背景。请先去除背景，或选择颜色区域。'));if(next.parts.length+regions.length>80)throw Error(t('Too many pieces. Select smaller groups or remove unused pieces first.','部件过多。请先选择较小区域或删除不用的部件。'));const names=[];for(const region of regions){const part=makePart(t('Image piece ','图像部件 ')+(next.parts.length+1),region.polygon,asset.id);part.z=next.parts.length;next.parts.push(part);names.push(part.id);}next=preservePhysicalScale(state.project,next);after={showArt:true,showConcept:false,selected:names[0],step:'refine',refineStage:'pieces'};reply=t('Review the extracted cut boundaries. Connected regions are not anatomical parts yet: split them at elbows, knees, or other movement points. Interior transparent details remain artwork, not automatic cutouts.','请检查提取的裁切轮廓。连通区域还不是解剖部件：可在肘、膝或其他活动位置分割。内部透明细节保留在图像中，不会自动变为镂空裁切。')+' '+(result.warnings||[]).join(' ');}
resetTool();proposeLocal(next,action==='remove-background'?t('Remove image background','去除图像背景'):t('Extract image pieces','提取图像部件'),reply,after);
}catch(error){if(imageOperation===operation)state.error=error.message;}finally{if(imageOperation===operation){imageOperation=null;state.busy=false;render();}}}

function createPanel(){const b=state.project.brief;return `<div class="eyebrow">${t('01 / Create','01 / 创作')}</div><h1>${t('Imagine your character.','想象你的角色。')}</h1><p class="intro">${t('Choose a starting point. Add the details that make it yours.','选择起点，加入属于你的细节。')}</p><form id="create-form" autocomplete="off"><div class="two-fields">${selectField('brief.kind',t('Character','角色'),[['','Your choice','自定义'],['human','Human','人物'],['animal','Animal','动物'],['creature','Creature','幻想生物'],['object','Object / custom','物品 / 自定义']],b.kind)}${selectField('brief.era',t('World','时代'),[['','Your choice','自定义'],['historical','Historical','历史'],['modern','Modern','现代'],['imagined','Imagined','想象世界']],b.era)}</div>${selectField('brief.style',t('Visual style','视觉风格'),[['','Your choice','自定义'],['traditional-inspired','Traditional-inspired','传统风格'],['paper-cut','Paper cut','剪纸'],['graphic','Bold graphic','鲜明图形'],['silhouette','Silhouette','剪影']],b.style)}${field(t('Your idea','你的想法'),`<textarea id="create-prompt" rows="5" maxlength="4000" placeholder="${t('A footballer in blue and gold, running beside a separate ball. Two arms, two legs, movable elbows and knees.','蓝金色球衣的足球运动员，跑向独立的足球。两臂两腿，肘部和膝盖可以活动。')}">${esc(state.prompt||b.keywords)}</textarea>`)}<p class="prompt-hint">${t('Include the costume, colors, number of limbs and what should move.','描述服装、颜色、肢体数量和活动部位。')}</p>${state.capabilities?.imageGeneration?btn(t('Generate character','生成角色'),'generate-image','primary full',state.busy):`<button type="submit" class="primary full" ${state.busy?'disabled':''}>${t('Draft editable pieces','生成可编辑草案')}</button>`}</form>${state.capabilities?.imageGeneration?`<details class="advanced-controls"><summary>${t('Other creation options','其他创作方式')}</summary>${btn(t('Draft a cutting plan from text','通过文字生成裁切草案'),'create-plan','secondary full',state.busy)}<p class="fine-print">${t('Experimental: review every proposed outline.','实验功能：请检查每个轮廓。')}</p></details>`:`<p class="connection-note">${t('Image generation is unavailable on this connection. You can import artwork below.','当前连接无法生成图片，可以在下方导入作品。')}</p>`}<div class="divider"><span>${t('or use your own image','或使用自己的图片')}</span></div>${btn(`<strong>${t('Import artwork','导入图片')}</strong><small>PNG · JPG · WebP</small>`,'import-art','upload-card')}<details class="starter-details"><summary>${t('Start with editable shapes','从可编辑形状开始')}</summary><p>${t('Choose a simple construction template, then make it your own.','选择简单结构模板，再自行修改。')}</p><div class="starter-grid">${[['figure','Jointed figure','关节人物'],['skirt','Wide sleeves & skirt','宽袖长裙'],['winged','Winged creature','有翼生物'],['tentacles','Tentacled character','触手角色']].map(([id,en,zh])=>btn(t(en,zh),'starter','secondary',state.busy,`data-kind="${id}"`)).join('')}</div></details>`;}

function refinePanel(){const stage=state.refineStage;return `<div class="eyebrow">${t('02 / Refine','02 / 修改')}</div><h1>${t('Make it move.','让角色动起来。')}</h1><nav class="refine-stages" aria-label="${t('Refinement steps','修改步骤')}">${[['clean','Clean image','清理图片'],['pieces','Choose pieces','选择部件'],['movement','Add movement','添加活动'],['test','Test','测试']].map(([id,en,zh],i)=>btn(`<span>${i+1}</span>${t(en,zh)}`,'refine-stage',stage===id?'active':'',false,`data-stage="${id}" ${stage===id?'aria-current="step"':''}`)).join('')}</nav>${['clean','pieces'].includes(stage)?imageToolsPanel():''}${stage==='pieces'?`<div class="tool-stack">${btn(t('Draw a custom piece','绘制自定义部件'),'draw',state.mode==='draw'?'tool active':'tool')}${btn(t('Split selected piece','分割所选部件'),'split-part','secondary',!selected()||selected().locked)}</div><p class="fine-print">${t('Select a piece on the canvas or in the list. Keep overlapping body parts separate.','在画布或列表中选择部件，将重叠的肢体分别制作。')}</p>`:''}${stage==='movement'?`<p class="intro">${t('Select a piece, then choose where it bends.','选择部件，再选择弯曲的位置。')}</p><div class="tool-stack">${btn(t('Split and add a hinge','分割并添加铰链'),'split-part','secondary',!selected()||selected().locked)}${btn(t('Join two pieces','连接两个部件'),'joint',state.mode==='joint'?'tool active':'tool',state.project.parts.length<2)}${btn(t('Add a control rod','添加操纵杆'),'rod',state.mode==='rod'?'tool active':'tool',!state.project.parts.length)}</div>${selectField('jointType',t('Joint type','关节类型'),[['pivot','Pivot · split pin','旋转关节 · 两脚钉'],['fixed','Fixed · glued overlap','固定连接 · 重叠粘接'],['hinge','Pin hinge','销轴铰链']],state.jointType)}<p class="fine-print">${t('A joint joins a parent and a child piece. Select overlapping pieces from the list before placing the pivot.','关节连接父部件与子部件。部件重叠时，先从列表选择，再放置转轴。')}</p>`:''}${stage==='test'?`<p class="intro">${t('Select a joint or its piece. Move the angle slider and inspect the full range.','选择关节或相应部件，拖动角度滑块，检查活动范围。')}</p><ul class="test-checklist"><li>${t('Do the pieces stay connected?','部件是否始终相连？')}</li><li>${t('Do they move without unwanted overlap?','活动时是否发生不必要的重叠？')}</li><li>${t('Is artwork missing behind a moving limb?','活动肢体后方是否缺少图案？')}</li></ul>${!state.project.joints.length?`<p class="connection-note">${t('No joints yet. Add a joint for movement, or continue with a static design.','尚无关节。添加关节实现活动，或继续制作静态作品。')}</p>`:''}`:''}<details class="advanced-controls"><summary>${t('Image assistance','图像辅助')}</summary><p>${t('Automatic image analysis and image editing depend on the AI connection. Local tracing and splitting are always available.','自动图像分析与编辑取决于 AI 连接。本地描图和分割始终可用。')}</p>${btn(t('Suggest pieces from image','根据图片建议部件'),'segment','secondary full',state.busy||!state.capabilities?.vision||!conceptAsset())}${btn(t('Review image with AI','使用 AI 检查图片'),'analyze','secondary full',state.busy||!state.capabilities?.vision||!conceptAsset())}${state.capabilities?.imageEditing?btn(t('Revise artwork image','修改角色图像'),'edit-image','secondary full',state.busy||!conceptAsset()):`<p class="fine-print">${t('Image editing is unavailable on this connection.','当前连接暂不支持图像编辑。')}</p>`}</details>`;}

function makePanel(){const diagnostics=validateStudio(state.project),errors=diagnostics.filter(d=>d.level==='error');return `<div class="eyebrow">${t('03 / Make','03 / 制作')}</div><h1>${t('Ready to make.','准备制作。')}</h1><p class="intro">${t('Set the size, check the pieces, then print a paper prototype.','设置尺寸，检查部件，然后打印纸样。')}</p><div class="size-settings"><h3>${t('Print size','打印尺寸')}</h3><div class="two-fields">${field(t('Height · mm','高度 · mm'),`<input type="number" min="1" max="1200" step=".1" data-field="heightMm" value="${Number(state.project.heightMm.toFixed(1))}">`)}${field(t('Hole · mm','孔径 · mm'),`<input type="number" min="1" max="12" step=".1" data-field="holeMm" value="${state.project.holeMm}">`)}</div>${field(t('Material thickness · mm','材料厚度 · mm'),`<input type="number" min=".1" max="10" step=".1" data-field="materialMm" value="${state.project.materialMm}">`)}</div><div class="checks ${errors.length?'has-error':''}"><h3>${errors.length?t('Resolve before export','导出前需处理'):t('Fabrication checks','制作检查')}</h3>${diagnostics.length?`<ul>${diagnostics.slice(0,10).map(d=>`<li class="${d.level}">${esc(d.message)}</li>`).join('')}</ul>`:`<p>${t('Geometry checks passed. Make a paper prototype to check strength and movement.','几何检查通过。请先制作纸样，检查强度与活动效果。')}</p>`}</div>${btn(t('Print pieces & assembly guide','打印部件与组装指南'),'print','primary full',!state.project.parts.length||!!errors.length)}<div class="two-buttons">${btn(t('Artwork SVG','作品 SVG'),'export-art','secondary',!state.project.parts.length||!!errors.length)}${btn(t('Cut outlines SVG','裁切轮廓 SVG'),'export-cut','secondary',!state.project.parts.length||!!errors.length)}</div><p class="fine-print">${t('Print at 100%. Measure the 50 mm calibration mark. Assemble a paper prototype to check joints, hidden artwork and fragile details.','按 100% 打印，测量 50 mm 校准标记。组装纸样，检查关节、遮挡图案和易损细节。')}</p>`;}

function partThumbnail(part){return `<span class="part-thumb" aria-hidden="true">${renderStudioSvg({...state.project,conceptAssetId:null,parts:[{...part,x:0,y:0,rotation:0}],joints:[],rods:[]},{interactive:false,showArt:true,showJoints:false,showRods:false,width:44,height:44})}</span>`;}
function revisionPanel(){const p=selected();return `<section class="revision-card"><h3>${t('Ask for a change','提出修改')}</h3><p class="scope-badge">${p?t('Selected piece only: ','仅修改所选部件：')+esc(p.name):t('Whole design · select a piece to focus the change','整个设计 · 选择部件可限定修改范围')}</p><form id="refine-form" autocomplete="off">${field(t('What should change?','想修改什么？'),`<textarea id="revision-prompt" rows="3" maxlength="4000" placeholder="${t('Make this forearm 15% longer.','将这个前臂加长 15%。')}">${esc(state.revisionPrompt)}</textarea>`)}<button type="submit" class="primary full" ${state.busy||!state.project.parts.length||p?.locked?'disabled':''}>${t('Preview change','预览修改')}</button></form><p class="fine-print">${p?.locked?t('Unlock this piece before changing it.','修改前请先解锁。'):t('Review before applying. New visual details need image editing.','先检查再应用。新增图像细节需要图像编辑功能。')}</p>${state.messages.length?`<details class="conversation"><summary>${t('Conversation','对话记录')} (${state.messages.length})</summary>${state.messages.slice(-6).map(m=>`<div class="message ${m.role}"><strong>${m.role==='user'?t('You','你'):t('Design assistant','设计助手')}</strong><p>${esc(m.content)}</p></div>`).join('')}</details>`:''}</section>`;}
function inspector(){const p=selected(),joint=p&&state.project.joints.find(j=>j.childId===p.id);return `<aside class="inspector" ${state.proposal?'hidden':''}><div class="panel-heading"><h2>${t('Your pieces','你的部件')}</h2><span class="count">${state.project.parts.length}</span></div><p class="panel-caption">${t('Select a piece to shape it or test its joint.','选择部件以修改形状或测试关节。')}</p><div class="part-list">${state.project.parts.length?state.project.parts.map(part=>`<button class="part-item ${state.selected===part.id?'selected':''}" data-action="select" data-id="${esc(part.id)}" aria-pressed="${state.selected===part.id}">${partThumbnail(part)}<span class="part-name">${esc(part.name)}</span><span class="part-badge">${part.locked?t('Locked','已锁定'):state.project.joints.some(j=>j.childId===part.id)?t('Joint','关节'):''}</span></button>`).join(''):`<p class="parts-empty">${t('Find a silhouette or draw your first piece.','提取轮廓或绘制第一个部件。')}</p>`}</div>${p?`<div class="part-properties"><div class="panel-heading"><h3>${esc(p.name)}</h3>${btn(p.locked?t('Unlock','解锁'):t('Lock','锁定'),'lock','small-button')}</div>${field(t('Piece name','部件名称'),`<input data-part-field="name" value="${esc(p.name)}" maxlength="80" ${p.locked?'disabled':''}>`)}${btn(t('Split this piece','分割此部件'),'split-part','secondary full',p.locked)}${dimensionControls(p)}${joint?`<section class="joint-control"><h3>${t('Test movement','测试活动')}</h3>${field(t('Joint angle','关节角度')+` <output id="angle-output">${joint.angle}°</output>`,`<input type="range" data-joint-field="angle" min="${joint.min}" max="${joint.max}" step="1" value="${joint.angle}" ${p.locked||joint.type==='fixed'?'disabled':''}>`)}<details class="advanced-controls"><summary>${t('Joint settings','关节设置')}</summary>${selectField('connection.type',t('Type','类型'),[['pivot','Pivot','旋转关节'],['fixed','Fixed','固定'],['hinge','Pin hinge','销轴铰链']],joint.type,p.locked?'disabled':'')}<div class="two-fields">${field(t('Min °','最小角度'),`<input type="number" data-joint-field="min" min="-180" max="180" value="${joint.min}" ${p.locked?'disabled':''}>`)}${field(t('Max °','最大角度'),`<input type="number" data-joint-field="max" min="-180" max="180" value="${joint.max}" ${p.locked?'disabled':''}>`)}</div>${field(t('Overlap radius · mm','重叠半径 · mm'),`<input type="number" data-joint-field="padRadius" min="0" max="${300/unitsPerMm(state.project)}" step=".1" value="${Number((joint.padRadius/unitsPerMm(state.project)).toFixed(2))}" ${p.locked?'disabled':''}>`)}${btn(t('Remove joint','移除关节'),'remove-joint','text-button danger',p.locked)}</details></section>`:connectionSuggestion(p)}<details class="advanced-controls"><summary>${t('Outline, layers & artwork','轮廓、图层与图案')}</summary>${btn(t('Edit outline points','编辑轮廓点'),'vertices',state.mode==='vertices'?'secondary full active':'secondary full',p.locked)}<div class="two-fields">${field(t('Backing color','底色'),`<input type="color" data-part-field="fill" value="${esc(p.fill||'#bc7653')}" ${p.locked?'disabled':''}>`)}${field(t('Layer','图层'),`<input type="number" data-part-field="z" value="${p.z||0}" min="-80" max="80" ${p.locked?'disabled':''}>`)}</div>${state.project.assets.length?field(t('Artwork','图案'),`<select data-part-field="assetId" ${p.locked?'disabled':''}><option value="">${t('Solid color','纯色')}</option>${state.project.assets.map(a=>`<option value="${esc(a.id)}" ${p.assetId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select>`):''}${!joint?`<div class="two-fields">${field('X',`<input type="number" data-part-field="x" value="${p.x||0}" ${p.locked?'disabled':''}>`)}${field('Y',`<input type="number" data-part-field="y" value="${p.y||0}" ${p.locked?'disabled':''}>`)}</div>`:''}${btn(t('Duplicate piece','复制部件'),'duplicate','secondary full',p.locked)}${btn(t('Delete piece','删除部件'),'delete-part','text-button danger full',p.locked)}</details></div>`:''}${revisionPanel()}${state.project.rods.length?`<details class="rod-list"><summary>${t('Control rods','操纵杆')} · ${state.project.rods.length}</summary>${state.project.rods.map(r=>`<div>${esc(state.project.parts.find(p=>p.id===r.partId)?.name||'Part')}${btn('×','remove-rod','small-button',false,`data-id="${esc(r.id)}" aria-label="${t('Remove rod','移除操纵杆')}"`)}</div>`).join('')}</details>`:''}</aside>`;}

function canvasBaseBox(project=state.project,imageOnly=false){if(imageOnly)return [0,0,project.canvas.width,project.canvas.height];const frame=projectBounds(project),w=Math.max(project.canvas.width,frame.maxX||0),h=Math.max(project.canvas.height,frame.maxY||0),x=Math.min(0,frame.minX||0),y=Math.min(0,frame.minY||0);return [x-60,y-60,w-x+120,h-y+120];}
function canvasViewBox(project=state.project,imageOnly=state.mode==='region'){return zoomViewBox(canvasBaseBox(project,imageOnly),state.camera);}
function canvasUnits(view=canvasViewBox()){const el=document.querySelector('#canvas-wrap'),box=el?.getBoundingClientRect?.();return screenUnitScale(view,box?.width||el?.clientWidth||640,box?.height||el?.clientHeight||640);}
function redrawCanvas(){const el=document.querySelector('#puppet-canvas');if(el)el.innerHTML=canvasContent();}
function focusVertex(index){root.querySelector(`[data-vertex-index="${index}"]`)?.focus?.();}
function canvasContent(project=state.project,mini=false,display={}){const imageOnly=display.imageOnly===true||(!mini&&state.mode==='region'),view=mini?null:canvasViewBox(project,imageOnly),unit=mini?1:canvasUnits(view);let svg=renderStudioSvg(imageOnly?{...project,parts:[],joints:[],rods:[]}:project,{selectedPartId:mini?null:state.selected,selectedJointId:mini?null:project.joints.find(j=>j.childId===state.selected)?.id,showJoints:state.showJoints,showRods:true,showArt:display.showArt??state.showArt,showConcept:(display.showConcept??state.showConcept)&&(display.showArt??state.showArt),interactive:!mini,draftPoints:[],...(!mini?{viewBox:view,markerSize:7*unit,hitRadius:22*unit}:{})});if(mini)return svg;let overlay='';if(state.points.length){overlay+=`<g class="trace-overlay" pointer-events="none"><polyline points="${state.points.map(p=>p.join(',')).join(' ')}"/><g>${state.points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="${5*unit}"/><text x="${x+8*unit}" y="${y-8*unit}" font-size="${14*unit}">${i+1}</text>`).join('')}</g></g>`;}
if(state.mode==='vertices'&&selected()){const p=selected(),matrix=partTransforms(project)[p.id];overlay+=`<g class="vertex-overlay">${p.polygon.map((point,i)=>{const [x,y]=transformPoint(matrix,point);return `<g data-vertex-index="${i}" tabindex="0" role="button" aria-label="${t('Outline point','轮廓点')} ${i+1}. ${t('Arrow keys move; Shift moves faster.','方向键移动；Shift 加速。')}"><circle class="vertex-hit" cx="${x}" cy="${y}" r="${22*unit}" style="fill:transparent;stroke:none" pointer-events="all"/><circle class="vertex-dot" cx="${x}" cy="${y}" r="${6*unit}" pointer-events="none"/></g>`;}).join('')}</g>`;}
if(state.jointStart){const matrix=partTransforms(project)[state.jointStart.partId],point=transformPoint(matrix,state.jointStart.point);overlay+=`<circle class="anchor-pending" cx="${point[0]}" cy="${point[1]}" r="${10*unit}" pointer-events="none"/>`;}
return svg.replace('</svg>',overlay+'</svg>');}
function toolHint(){if(state.mode==='pan')return `<strong>${t('Drag to move the view','拖动以移动视图')}</strong><span>${t('Your puppet stays unchanged. Use Fit to see it all.','角色保持不变。使用适应按钮查看全图。')}</span>${btn(t('Done','完成'),'cancel-tool','small-button')}`;if(state.mode==='split')return `<strong>${t('Place two points across the selected piece','在所选部件两侧放置两个点')}</strong><span>${t('Cut across one narrow section, such as a neck or elbow. The line must cross the outline twice; use tracing for overlapping limbs.','在颈部或肘部等较窄位置切割，连线只能与轮廓相交两次。重叠肢体可手动描图。')}</span>${btn(t('Undo point','撤销点'),'undo-point','small-button',!state.points.length)}${btn(t('Preview split','预览分割'),'preview-split','primary small-button',state.points.length!==2)}${btn('×','cancel-tool','small-button')}`;if(state.mode==='axis')return `<strong>${t('Click two points along the length direction','沿长度方向点击两个点')}</strong><span>${t('The current artwork stays unchanged.','当前图像保持不变。')}</span>${btn('×','cancel-tool','small-button')}`;if(state.mode==='region')return `<strong>${t('Click a connected color region in the original image','点击原图中连通的颜色区域')}</strong><span>${t('This selects similar pixels, not body parts. Adjust tolerance if needed.','此工具选择相似像素，不识别身体部件。可按需调整容差。')}</span>${btn('×','cancel-tool','small-button')}`;if(state.mode==='draw')return `<strong>${t('Trace the boundary','描出轮廓')}</strong><span>${t('Click around a piece. Finish with at least 3 points.','沿部件边界点击，至少绘制 3 个点后完成。')}</span>${btn(t('Undo point','撤销点'),'undo-point','small-button',!state.points.length)}${btn(t('Finish part','完成部件'),'finish-part','primary small-button',state.points.length<3)}${btn('×','cancel-tool','small-button')}`;if(state.mode==='joint')return `<strong>${state.jointStart?t('2. Choose the child’s pivot','2. 选择子部件的转轴点'):t('1. Choose the parent’s pivot','1. 选择父部件的转轴点')}</strong><span>${t('Click a point inside each piece. Overlapping pieces can be selected in the parts list first.','在两个部件内部各点击一点。重叠部件可先从列表选择。')}</span>${btn('×','cancel-tool','small-button')}`;if(state.mode==='rod')return `<strong>${t('Click a control-rod attachment point','点击操纵杆连接位置')}</strong>${btn('×','cancel-tool','small-button')}`;if(state.mode==='vertices')return `<strong>${t('Drag the outline points','拖动轮廓点')}</strong><span>${t('Drag a point or focus it and use arrow keys. Hold Shift for larger steps. Keep edges from crossing.','拖动轮廓点，或选中后使用方向键。按住 Shift 可加大步幅。避免边线交叉。')}</span>${btn(t('Done','完成'),'cancel-tool','small-button')}`;return '';}
function proposalView(){if(!state.proposal)return '';const imageReview=state.proposalAfter?.imageReview,display=imageReview?{imageOnly:true,showArt:true,showConcept:true}:{};return `<section class="proposal-review ${imageReview?'image-review':''}" aria-labelledby="review-heading"><div class="proposal-heading"><div><span class="eyebrow">${t('YOUR DECISION','由你决定')}</span><h2 id="review-heading" tabindex="-1">${imageReview?t('Does this match your idea?','这符合你的想法吗？'):t('Review the change','检查修改')}</h2></div></div>${imageReview?`<p class="review-checklist">${t('Check: limbs & count · costume · separate props','检查：肢体与数量 · 服装 · 独立道具')}</p>`:''}<p class="review-explanation">${esc(state.reply)}</p><div class="review-toggle" aria-label="${t('Compare designs','对比设计')}">${[['before','Before','原设计'],['after','Proposed','新方案'],['both','Compare both','查看两种设计']].map(([id,en,zh])=>btn(t(en,zh),'review-view',state.reviewView===id?'active':'',false,`data-view="${id}" aria-pressed="${state.reviewView===id}"`)).join('')}</div><div class="comparison" data-review-view="${state.reviewView}"><div class="comparison-before"><span>${t('Before','原设计')}</span>${canvasContent(state.proposalBase,true,display)}</div><div class="comparison-after"><span>${t('Proposed','新方案')}</span>${canvasContent(state.proposal,true,display)}</div></div><div class="proposal-actions">${btn(t('Keep original','保留原设计'),'reject','secondary')}${btn(imageReview?t('Use this character →','使用此角色 →'):t('Apply this change','应用修改'),'accept','primary')}</div></section>`;}

function settingsView(){return `<div class="modal-backdrop"><section class="settings-card" role="dialog" aria-modal="true" aria-label="${t('AI status','AI 状态')}"><div class="panel-heading"><h2>${t('AI status','AI 状态')}</h2>${btn('×','settings','small-button')}</div><p>${t('Use a protected studio relay URL. API keys belong on the server and are never entered here.','使用受保护的工作室中继地址。API 密钥仅保存在服务器端，不在此输入。')}</p>${field(t('Protected endpoint','受保护的接口地址'),`<input id="relay-url" type="url" placeholder="https://your-relay.example/api/studio" value="${esc(state.endpoint)}">`)}${btn(t('Save & check connection','保存并检查连接'),'save-endpoint','primary full')}<div class="capability-list">${['text','vision','imageGeneration','imageEditing'].map(key=>`<div><span>${t({text:'Editable design proposals',vision:'Image analysis',imageGeneration:'Image generation',imageEditing:'Image editing'}[key],{text:'可编辑设计方案',vision:'图片分析',imageGeneration:'图像生成',imageEditing:'图像编辑'}[key])}</span><strong>${state.capabilities?.[key]?t('Available','可用'):t('Not available','不可用')}</strong></div>`).join('')}</div><p class="fine-print">${esc(state.capabilities?.status||state.capabilities?.message||'')}</p><a href="https://github.com/zhinii/bnta-shadow-puppet-studio/blob/main/integration/STUDIO-V2-RELAY.md" target="_blank" rel="noopener">${t('Relay setup instructions','中继配置说明')}</a></section></div>`;}

function nextAction(){if(state.step==='create')return (state.project.assets.length||state.project.parts.length)?btn(t('Continue to Refine →','继续修改 →'),'next-stage','primary'):'';if(state.step==='make')return btn(t('Back to movement','返回活动测试'),'refine-stage','secondary',false,'data-stage="test"');const next={clean:['Choose pieces →','选择部件 →'],pieces:['Add movement →','添加活动 →'],movement:['Test movement →','测试活动 →'],test:['Prepare to make →','准备制作 →']}[state.refineStage];return btn(t(...next),'next-stage','primary',state.refineStage!=='clean'&&!state.project.parts.length);}
function render(){const ui=resettingSession?null:captureUIState(root);document.documentElement.lang=state.project.language;root.innerHTML=`<header class="topbar"><a class="brand" href="#" aria-label="Shadow Puppet Studio"><span class="brand-mark">✦</span><span>${t('Shadow Puppet Studio','皮影设计工作室')}<small>BNTA</small></span></a><input class="project-title" ${state.proposal?'disabled':''} data-field="title" maxlength="100" value="${esc(state.project.title)}" placeholder="${t('Untitled puppet','未命名角色')}" aria-label="${t('Project title','项目名称')}"><div class="top-actions"><span id="save-status" class="session-status"></span>${btn(state.project.language==='en'?'中文':'EN','language','top-button',!!state.proposal)}<details class="project-menu"><summary>${t('Project','项目')}</summary><div class="project-menu-panel">${field(t('Project name','项目名称'),`<input data-field="title" ${state.proposal?'disabled':''} maxlength="100" value="${esc(state.project.title)}">`)}<p>${t('Closing or reloading starts a new session. Download a project to keep it.','关闭或刷新后会重新开始。请下载项目以保存作品。')}</p>${btn(t('Download project','下载项目'),'save-project','primary full')}${btn(t('Open project file','打开项目文件'),'open-project','secondary full')}${btn(t('New project','新建项目'),'new-project','text-button full')}</div></details></div></header><nav class="steps" aria-label="${t('Design process','设计流程')}">${[['create','Create','创作'],['refine','Refine','修改'],['make','Make','制作']].map(([id,en,zh],i)=>`<button class="step ${state.step===id?'current':''}" data-action="step" data-step="${id}" ${state.step===id?'aria-current="step"':''}><span class="step-number">${i+1}</span><span>${t(en,zh)}</span></button>`).join('')}<div class="nav-spacer"></div>${btn(t('AI status','AI 状态'),'settings','connection-button',false,'id="ai-status-button"')}</nav><main class="workspace step-${state.step} ${state.proposal?'reviewing':''}"><section class="work-panel"><fieldset class="panel-controls" ${state.proposal?'disabled':''}>${state.step==='create'?createPanel():state.step==='refine'?refinePanel():makePanel()}</fieldset></section><section class="canvas-panel ${state.proposal?'review-active':''}">${state.error?`<div class="error-banner" role="alert">${esc(state.error)}${btn('×','dismiss-error','small-button',false,`aria-label="${t('Dismiss error','关闭错误提示')}"`)}</div>`:''}${state.notice?`<div class="notice-banner" role="status"><p>${esc(state.notice)}</p>${btn('×','dismiss-notice','small-button',false,`aria-label="${t('Dismiss advice','关闭建议')}"`)}</div>`:''}${state.busy?`<div class="busy-banner" role="status"><span class="spinner"></span>${t('Working on your request…','正在处理请求…')}${btn(t('Cancel','取消'),'cancel-ai','text-button')}</div>`:''}${state.proposal?proposalView():`<div class="canvas-toolbar"><div class="view-switch">${btn(t('Artwork','图案'),'view-art',state.showArt?'active':'')}${btn(t('Shadow','剪影'),'view-shadow',!state.showArt?'active':'')}</div><div class="view-options"><label><input type="checkbox" data-view="joints" ${state.showJoints?'checked':''}>${t('Joints','关节')}</label>${state.project.conceptAssetId?`<label><input type="checkbox" data-view="concept" ${state.showConcept?'checked':''}>${t('Reference','原图')}</label>`:''}</div><div class="canvas-zoom">${btn('−','zoom-out','',state.camera.zoom<=1,`aria-label="${t('Zoom out','缩小')}"`)}<output>${Math.round(state.camera.zoom*100)}%</output>${btn('+','zoom-in','',state.camera.zoom>=6,`aria-label="${t('Zoom in','放大')}"`)}${btn(t('Fit','适应'),'zoom-fit')}${btn(t('Pan','平移'),'pan',state.mode==='pan'?'active':'',false,`aria-pressed="${state.mode==='pan'}"`)}</div></div><div class="canvas-wrap ${!state.showArt?'shadow-view':''} mode-${state.mode}" id="canvas-wrap" tabindex="0" aria-label="${t('Puppet canvas. Use Pan to move the view.','角色画布。使用平移工具移动视图。')}"><div id="puppet-canvas">${canvasContent()}</div>${!state.project.parts.length&&!state.project.assets.length?`<div class="empty-canvas"><span class="empty-emblem">✦</span><h2>${t('Your character starts here','你的角色从这里开始')}</h2><p>${t('Describe an idea, import an image, or draw a shape.','描述想法、导入图片或绘制形状。')}</p>${btn(t('Draw a custom shape','绘制自定义形状'),'draw','secondary')}</div>`:''}</div>${state.mode!=='select'?`<div class="tool-hint" role="status">${toolHint()}</div>`:''}<div class="canvas-footer"><span>${state.project.parts.length} ${t('pieces','个部件')} · ${state.project.joints.length} ${t('joints','个关节')}</span><div>${btn('↶','undo','icon-button',!state.undo.length,`aria-label="${t('Undo','撤销')}"`)}${btn('↷','redo','icon-button',!state.redo.length,`aria-label="${t('Redo','重做')}"`)}</div><span>${Number(state.project.heightMm.toFixed(1))} mm</span></div><div class="task-next">${nextAction()}</div>`}</section>${state.step==='refine'&&!state.proposal?inspector():''}</main><footer class="page-footer"><span>${t('This session clears when you close or reload. Download to keep your work.','关闭或刷新后会清空本次会话。请下载以保存作品。')}</span><a href="${new URL('./legacy.html',import.meta.url).href}">${t('Classic editor','经典编辑器')}</a></footer>${state.settings?settingsView():''}`;status();const newReview=state.proposal&&lastReview!==state.proposal;restoreUIState(root,ui,{focus:!newReview});if(newReview){document.querySelector('#review-heading')?.focus?.();document.querySelector('.canvas-panel')?.scrollIntoView?.({behavior:'smooth',block:'start'});}lastReview=state.proposal;if(typeof requestAnimationFrame==='function')requestAnimationFrame(()=>{if(!drag&&!state.proposal){const focus=document.activeElement;if(!focus?.closest?.('#puppet-canvas'))redrawCanvas();}});}

async function checkConnection(){try{state.capabilities=await getStudioCapabilities(state.endpoint?{endpoint:state.endpoint}:{});}catch(error){state.capabilities={text:false,vision:false,imageGeneration:false,message:error.message};}render();}
async function aiRequest(task){if(state.busy)return;const prompt=task==='create'||task==='generate-image'?state.prompt||state.project.brief.keywords:state.revisionPrompt;
if(!prompt.trim()&&!['segment','analyze'].includes(task)){state.error=t('Describe your character or the change you want first.','请先描述角色或修改需求。');render();return;}
if(task==='refine'&&!state.project.parts.length)return;
const asset=state.project.assets.find(a=>a.id===state.project.conceptAssetId);const requestPrompt=prompt|| (task==='segment'?t('Suggest separate movable puppet parts for this artwork. Preserve the silhouette and visible details.','为此图像建议独立的可活动皮影部件，保留轮廓和可见细节。'):t('Review this character as a physical shadow puppet: identify movement, connections, hidden overlap artwork, and fragile areas.','检查此角色作为实体皮影的可行性：分析活动、连接、遮挡的重叠区域和脆弱部位。'));
if(task==='create'&&state.project.parts.some(p=>p.locked)){state.error=t('Create replaces the design. Unlock parts first, or use Refine to keep them.','构思将替换设计。请先解锁部件，或使用修改功能保留它们。');render();return;}
const original=structuredClone(state.project),base=structuredClone(state.project),version=state.version;if(task==='create'){base.parts=[];base.joints=[];base.rods=[];base.revisions=[];}state.busy=true;state.error='';state.notice='';state.proposal=null;state.proposalLabel='';state.proposalAfter=null;state.proposalVersion=version;const requestController=new AbortController();controller=requestController;const timeout=setTimeout(()=>requestController.abort(),['generate-image','edit-image'].includes(task)?240000:150000);state.messages.push({role:'user',content:requestPrompt});render();
try{const sendImage=task!=='generate-image'&&(['analyze','segment','edit-image'].includes(task)||state.capabilities?.vision);const result=await requestStudioAI(base,{task,prompt:requestPrompt,selectedPartId:task==='refine'?state.selected:null,imageDataUrl:sendImage?asset?.dataUrl:undefined,history:state.messages.slice(-5),capabilities:state.capabilities,signal:requestController.signal,...(state.endpoint?{endpoint:state.endpoint}:{})});if(requestController.signal.aborted||controller!==requestController)return;state.reply=result.reply;state.messages.push({role:'assistant',content:result.reply});if(version!==state.version){state.error=t('The design changed while AI was working. Please request a fresh proposal.','AI 工作期间设计已更改，请重新请求方案。');return;}
let proposal=null;if(result.asset){state.proposalAfter={imageReview:true,showArt:true,showConcept:true,step:'refine',refineStage:'clean',selected:null};if(task==='generate-image'&&base.parts.length)result.warnings=[...(result.warnings||[]),t('This is new artwork. Existing pieces keep their original images; use Image to pieces to create parts from the new reference.','这是新生成的图像。原部件保留原图，请使用图像转部件工具处理新参考图。')];const normalizedAsset={...result.asset,id:result.asset.id||uid()};base.assets.push(normalizedAsset);if(task==='edit-image'&&asset){if(asset.width!==normalizedAsset.width||asset.height!==normalizedAsset.height){result.warnings=[...(result.warnings||[]),t('Image framing changed. Existing part artwork is preserved; trace the new reference to align new parts.','图像尺寸已改变。已保留原部件图像，请根据新参考图重新描绘部件。')];}else{for(const part of base.parts)if(!part.locked&&part.assetId===asset.id)part.assetId=normalizedAsset.id;result.warnings=[...(result.warnings||[]),t('Check the cut edges against the revised artwork; pixel edits may shift details.','请检查裁切轮廓与修改后图像的对应关系，图像修改可能改变细节位置。')];}}base.conceptAssetId=normalizedAsset.id;base.canvas={width:normalizedAsset.width,height:normalizedAsset.height};proposal=base;}
if(result.proposal){proposal=applyStudioProposal(base,result.proposal);if(task!=='create')proposal=preservePhysicalScale(original,proposal);}
if(proposal){state.reviewView='after';state.proposal=normalizeStudioProject(proposal);state.proposalBase=original;}else if(!result.reply){state.error=t('No design was returned. Your work is unchanged.','未返回设计，当前作品保持不变。');}if(result.warnings?.length){state.reply=[result.reply,...result.warnings].join('\n\n');state.messages[state.messages.length-1].content=state.reply;}if(!proposal&&result.reply&&task!=='analyze')state.notice=t('Advice only — no editable pieces were created or changed. ','仅提供建议，尚未创建或修改可编辑部件。 ')+state.reply;if(task==='analyze'){state.step='refine';toast(t('Image review added to the conversation.','图片分析已添加至对话。'));}}
catch(error){if(controller!==requestController)return;state.error=error.name==='AbortError'?t('Request cancelled. Your work is unchanged.','请求已取消，作品未更改。'):error.message;}
finally{clearTimeout(timeout);if(controller===requestController){state.busy=false;controller=null;render();}}}

function screenPoint(event){const svg=document.querySelector('#puppet-canvas svg');if(!svg)return null;const p=svg.createSVGPoint();p.x=event.clientX;p.y=event.clientY;const matrix=svg.getScreenCTM();if(!matrix)return null;const result=p.matrixTransform(matrix.inverse());return [Math.round(result.x*10)/10,Math.round(result.y*10)/10];}
function localPoint(partId,point){const m=partTransforms(state.project)[partId],det=m[0]*m[3]-m[1]*m[2];if(!det)throw Error('Invalid transform');const x=point[0]-m[4],y=point[1]-m[5];return [(m[3]*x-m[2]*y)/det,(-m[1]*x+m[0]*y)/det];}
function canvasClick(event){if(suppressCanvasClick){suppressCanvasClick=false;return;}if(drag?.moved||state.mode==='pan'||state.mode==='vertices')return;const jointHit=event.target.closest('[data-joint-id]')?.dataset.jointId;if(state.mode==='select'&&jointHit){const j=state.project.joints.find(j=>j.id===jointHit);if(j)choosePart(j.childId);return;}const point=screenPoint(event);if(!point)return;const hit=event.target.closest('[data-part-id]')?.dataset.partId;const partId=state.mode==='select'?hit:state.selected||hit;
if(state.mode==='region'){runImageTool('select-region',point.map(Math.round));return;}if(state.mode==='split'||state.mode==='axis'){if(!selected()||selected().locked)return;if(state.points.length===2)state.points=[];state.points.push(point);if(state.mode==='axis'&&state.points.length===2){try{const a=localPoint(state.selected,state.points[0]),b=localPoint(state.selected,state.points[1]);if(Math.hypot(b[0]-a[0],b[1]-a[1])<2)throw Error(t('Choose two distinct points.','请选择两个不同的点。'));const angle=Math.atan2(b[1]-a[1],b[0]-a[0])*180/Math.PI-90;const next=setPartParameterAxis(state.project,state.selected,((angle+540)%360)-180);resetTool();commit(next,t('Set part direction','设置部件方向'));}catch(error){state.error=error.message;render();}}else render();return;}if(state.mode==='draw'){if(state.points.length>=500){toast('Finish this outline before adding more points.');return;}state.points.push(point);render();return;}if(state.mode==='joint'&&partId){const part=state.project.parts.find(p=>p.id===partId);if(part?.locked){toast(t('Unlock this part first.','请先解锁此部件。'));return;}if(!state.jointStart){state.jointStart={partId,point:localPoint(partId,point)};state.selected=null;render();return;}if(partId===state.jointStart.partId){toast(t('Choose a different child part.','请选择另一个子部件。'));return;}try{const next=addConnection(state.project,{id:uid(),parentId:state.jointStart.partId,childId:partId,parentAnchor:state.jointStart.point,childAnchor:localPoint(partId,point),type:state.jointType,angle:0,min:-90,max:90,padRadius:unitsPerMm(state.project)*(state.jointType==='fixed'?Math.max(3,state.project.materialMm+1):state.project.holeMm/2+Math.max(1,state.project.materialMm)+.5)});resetTool();state.selected=partId;commit(preservePhysicalScale(state.project,next),t('Add connection','添加连接'));}catch(e){state.error=e.message;render();}return;}
if(state.mode==='rod'&&partId){const p=state.project.parts.find(p=>p.id===partId);if(p.locked){toast(t('Unlock this part first.','请先解锁部件。'));return;}const local=localPoint(partId,point);resetTool();mutate(next=>next.rods.push({id:uid(),partId,point:local}),t('Add rod point','添加操纵杆连接点'));return;}
if(state.mode==='select'){if(state.selected!==hit)state.connectParent='';state.selected=hit||null;render();}}

root.addEventListener('click',async event=>{if(event.target.closest('#puppet-canvas')){canvasClick(event);return;}const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(state.proposal&&!['accept','reject','review-view','new-project','save-project','open-project','settings','save-endpoint','dismiss-error','dismiss-notice','cancel-ai'].includes(a))return;try{
if(a==='step'){resetTool();state.step=el.dataset.step;render();}
else if(a==='refine-stage'){resetTool();state.step='refine';state.refineStage=el.dataset.stage;render();}
else if(a==='next-stage'){resetTool();if(state.step==='create'){state.step='refine';state.refineStage=conceptAsset()?'clean':'pieces';}else if(state.refineStage==='test')state.step='make';else state.refineStage={clean:'pieces',pieces:'movement',movement:'test'}[state.refineStage]||'pieces';render();}
else if(a==='review-view'){state.reviewView=['before','after','both'].includes(el.dataset.view)?el.dataset.view:'after';render();}
else if(a==='zoom-in'||a==='zoom-out'||a==='zoom-fit'){state.camera=a==='zoom-fit'?{zoom:1,x:0,y:0}:normalizeCamera({...state.camera,zoom:state.camera.zoom*(a==='zoom-in'?1.25:.8)});render();}
else if(a==='pan'){const wasPan=state.mode==='pan';resetTool();if(!wasPan)state.mode='pan';render();}
else if(a==='language'){mutate(p=>{p.language=p.language==='en'?'zh':'en';},'Language');}
else if(a==='select')choosePart(el.dataset.id);
else if(a==='undo'||a==='redo'){const from=a==='undo'?state.undo:state.redo,to=a==='undo'?state.redo:state.undo;if(from.length){to.push(state.project);state.project=from.pop();state.version++;state.proposal=null;resetTool();sessionChanged();render();}}
else if(a==='save-project'){download(safeName()+'.puppet.json',serializeStudioProject(state.project),'application/json');state.saveStatus='downloaded';status();toast(t('Project downloaded with its artwork.','项目及作品图片已下载。'));}
else if(a==='open-project')document.querySelector('#project-file').click();
else if(a==='import-art')document.querySelector('#artwork-file').click();
else if(a==='new-project')resetSession();
else if(a==='starter'){if(state.project.parts.some(p=>p.locked))throw Error(t('Unlock the current parts before replacing the construction.','替换结构前请先解锁当前部件。'));const next=createStarter(el.dataset.kind,{language:state.project.language});next.title=state.project.title;next.brief=state.project.brief;next.assets=state.project.assets;next.conceptAssetId=state.project.conceptAssetId;commit(next,t('Choose construction template','选择结构模板'));state.selected=next.parts[0]?.id;state.showConcept=false;state.step='refine';state.refineStage='pieces';render();}
else if(a==='view-art'||a==='view-shadow'){state.showArt=a==='view-art';render();}
else if(a==='remove-background'||a==='extract-silhouette')await runImageTool(a);
else if(a==='select-region'){state.showArt=true;state.showConcept=true;state.selected=null;beginTool('region');}
else if(a==='split-part'&&selected()&&!selected().locked)beginTool('split');
else if(a==='parameter-axis'&&selected()&&!selected().locked)beginTool('axis');
else if(a==='preview-split'&&selected()&&state.points.length===2){const points=state.points.map(p=>localPoint(state.selected,p));const result=splitPart(state.project,state.selected,points[0],points[1],{connect:true,type:state.jointType});resetTool();proposeLocal(result.project,t('Split into hinged pieces','分割成铰接部件'),t('Review the two pieces and their shared pivot. Overlap tabs support the joint; check the printed detail in that area before cutting.','请检查两个部件及其共用转轴。重叠连接片为关节提供支撑，裁切前请检查该区域的图像细节。')+' '+(result.warnings||[]).join(' '),{selected:result.partIds[1],showConcept:false,step:'refine',refineStage:'movement'});}
else if(a==='suggest-connection'&&selected()&&state.connectParent){const result=suggestConnection(state.project,state.connectParent,state.selected,{type:state.jointType});proposeLocal(result.project,t('Accept suggested connection','接受建议连接'),t('This pivot was suggested from the chosen pieces and their distance, not anatomical recognition. Review its position and movement.','此转轴根据所选部件及其距离计算，并非解剖识别结果。请检查其位置与运动。')+' '+(result.warnings||[]).join(' '),{showConcept:false,step:'refine'});}
else if(['draw','joint','rod'].includes(a))beginTool(a);
else if(a==='cancel-tool'){resetTool();render();}
else if(a==='undo-point'){state.points.pop();render();}
else if(a==='finish-part'){if(state.points.length<3)return;const part=makePart(t('Part ','部件 ')+(state.project.parts.length+1),state.points,state.project.conceptAssetId);const next=structuredClone(state.project);next.parts.push(part);resetTool();state.selected=part.id;commit(preservePhysicalScale(state.project,next),t('Draw custom part','绘制自定义部件'));}
else if(a==='vertices'){const mode=state.mode==='vertices'?'select':'vertices';resetTool();state.mode=mode;render();}
else if(a==='lock'){mutate(p=>{const part=p.parts.find(x=>x.id===state.selected);part.locked=!part.locked;},t('Lock / unlock part','锁定 / 解锁部件'));}
else if(a==='duplicate'&&selected()&&!selected().locked){const part=structuredClone(selected()),matrix=partTransforms(state.project)[part.id];part.id=uid();part.name+=' '+t('copy','副本');part.x=matrix[4]+25;part.y=matrix[5]+25;part.rotation=Math.atan2(matrix[1],matrix[0])*180/Math.PI;state.selected=part.id;mutate(p=>p.parts.push(part),t('Duplicate part','复制部件'));}
else if(a==='delete-part'&&selected()&&!selected().locked){const id=state.selected,transforms=partTransforms(state.project);mutate(p=>{for(const joint of p.joints.filter(j=>j.parentId===id)){const child=p.parts.find(p=>p.id===joint.childId);if(child.locked)throw Error(t('Unlock connected child parts before deleting their parent.','删除父部件前请先解锁连接的子部件。'));const m=transforms[child.id];child.x=m[4];child.y=m[5];child.rotation=Math.atan2(m[1],m[0])*180/Math.PI;}p.parts=p.parts.filter(x=>x.id!==id);p.joints=p.joints.filter(j=>j.parentId!==id&&j.childId!==id);p.rods=p.rods.filter(r=>r.partId!==id);},t('Delete part','删除部件'));}
else if(a==='remove-joint'&&selected()&&!selected().locked){const m=partTransforms(state.project)[state.selected];mutate(p=>{p.joints=p.joints.filter(j=>j.childId!==state.selected);const part=p.parts.find(x=>x.id===state.selected);part.x=m[4];part.y=m[5];part.rotation=Math.atan2(m[1],m[0])*180/Math.PI;},t('Remove connection','移除连接'));}
else if(a==='remove-rod')mutate(p=>{p.rods=p.rods.filter(r=>r.id!==el.dataset.id);},t('Remove rod','移除操纵杆'));
else if(a==='accept'&&state.proposal){if(state.proposalVersion!==null&&state.proposalVersion!==state.version)throw Error(t('The project changed. Review a fresh proposal.','项目已改变，请重新审核方案。'));const proposal=state.proposal,after=state.proposalAfter;commit(proposal,state.proposalLabel||t('Accept AI proposal','接受 AI 方案'));state.proposalLabel='';state.proposalAfter=null;state.proposalVersion=null;state.showConcept=true;if(!after){state.step='refine';state.refineStage='pieces';}if(after){const {imageReview,...updates}=after;if(imageReview){resetTool();state.connectParent='';state.camera={zoom:1,x:0,y:0};}Object.assign(state,updates);}render();}
else if(a==='reject'){state.proposal=null;state.proposalLabel='';state.proposalAfter=null;state.proposalVersion=null;render();}
else if(a==='dismiss-error'){state.error='';render();}
else if(a==='dismiss-notice'){state.notice='';render();}
else if(a==='cancel-ai')controller?.abort();
else if(a==='create-plan')await aiRequest('create');
else if(['segment','analyze','generate-image','edit-image'].includes(a))await aiRequest(a);
else if(a==='print'){const html=exportPrintHtml(state.project);const frame=document.querySelector('#print-frame');frame.onload=()=>{const doc=frame.contentDocument;Promise.all(Array.from(doc.images||[]).map(img=>img.decode?.().catch(()=>{})||Promise.resolve())).then(()=>{if(frame.srcdoc!==html)return;frame.contentWindow.focus();frame.contentWindow.print();});};frame.srcdoc=html;}
else if(a==='export-art'||a==='export-cut')download(safeName()+(a==='export-cut'?'-cut':'-artwork')+'.svg',exportSheetSvg(state.project,{cutOnly:a==='export-cut'}),'image/svg+xml');
else if(a==='settings'){state.settings=!state.settings;render();document.querySelector(state.settings?'#relay-url':'#ai-status-button')?.focus?.();}
else if(a==='save-endpoint'){const value=document.querySelector('#relay-url').value.trim();if(value){const url=new URL(value);if(url.protocol!=='https:'&&!['localhost','127.0.0.1'].includes(url.hostname))throw Error(t('Use an HTTPS protected relay URL.','请使用 HTTPS 中继地址。'));if(url.username||url.password||url.search||url.hash)throw Error(t('Use a URL without credentials or query parameters.','地址中不能含有凭据或查询参数。'));}state.endpoint=value;try{localStorage.setItem('bnta-studio-endpoint',value);}catch{}await checkConnection();}
}catch(error){state.error=error.message;render();}});

root.addEventListener('input',event=>{if(state.proposal)return;const el=event.target;if(el.dataset.field==='title'){state.project={...state.project,title:el.value};state.version++;sessionChanged();return;}if(el.dataset.imageTolerance!==undefined){state.imageTolerance=Number(el.value);const out=document.querySelector('#tolerance-output');if(out)out.textContent=el.value;return;}if(el.dataset.paramField&&selected()&&!selected().locked){const key=el.dataset.paramField;try{const preview=resizePart(state.project,state.selected,{[key]:Number(el.value)/100});const out=document.querySelector('#parameter-'+key+'-output');if(out)out.textContent=el.value+'%';const canvas=document.querySelector('#puppet-canvas');if(canvas)canvas.innerHTML=canvasContent(preview);}catch{}return;}if(el.id==='create-prompt'){state.prompt=el.value;state.project={...state.project,brief:{...state.project.brief,keywords:el.value}};state.version++;sessionChanged();}if(el.id==='revision-prompt')state.revisionPrompt=el.value;if(el.dataset.jointField==='angle'){const out=document.querySelector('#angle-output');if(out)out.textContent=el.value+'°';const preview=structuredClone(state.project),joint=preview.joints.find(j=>j.childId===state.selected);if(joint){joint.angle=Number(el.value);const canvas=document.querySelector('#puppet-canvas');if(canvas)canvas.innerHTML=canvasContent(preview);}}});
root.addEventListener('change',event=>{if(state.proposal)return;const el=event.target;try{if(el.dataset.imageTolerance!==undefined){state.imageTolerance=Number(el.value);return;}if(el.dataset.connectParent!==undefined){state.connectParent=el.value;render();return;}if(el.dataset.paramField&&selected()&&!selected().locked){const next=resizePart(state.project,state.selected,{[el.dataset.paramField]:Number(el.value)/100});commit(next,t('Resize artwork and part','调整图像和部件尺寸'));return;}if(el.dataset.paramAxis!==undefined&&selected()&&!selected().locked){commit(setPartParameterAxis(state.project,state.selected,Number(el.value)),t('Set part direction','设置部件方向'));return;}if(el.dataset.sourceArt!==undefined){const asset=state.project.assets.find(a=>a.id===el.value);if(!asset)return;mutate(p=>{p.conceptAssetId=asset.id;p.canvas={width:asset.width,height:asset.height};},t('Choose source image','选择原始图像'));state.showArt=true;state.showConcept=true;resetTool();render();return;}if(el.dataset.view){if(el.dataset.view==='joints')state.showJoints=el.checked;else state.showConcept=el.checked;render();return;}if(el.dataset.field==='jointType'){state.jointType=el.value;return;}if(el.dataset.field==='connection.type'){if(selected()?.locked)return;mutate(p=>{const j=p.joints.find(j=>j.childId===state.selected);const wasFixed=j.type==='fixed';j.type=el.value;if(j.type==='fixed')j.angle=0;else if(wasFixed&&j.min===j.max){j.min=-90;j.max=90;}},t('Change connection','修改连接'));return;}if(el.dataset.field){const path=el.dataset.field,value=el.type==='number'?Number(el.value):el.value;mutate(p=>{if(path.startsWith('brief.'))p.brief[path.slice(6)]=value;else p[path]=value;},t('Update design settings','修改设计设置'),{keepScale:path!=='heightMm'});return;}if(el.dataset.partField&&selected()&&!selected().locked){const key=el.dataset.partField,value=['x','y','z'].includes(key)?Number(el.value):el.value;mutate(p=>{p.parts.find(x=>x.id===state.selected)[key]=key==='assetId'?(value||null):value;},t('Edit part','编辑部件'));return;}if(el.dataset.jointField&&selected()&&!selected().locked){const key=el.dataset.jointField;mutate(p=>{const j=p.joints.find(j=>j.childId===state.selected);j[key]=Number(el.value)*(key==='padRadius'?unitsPerMm(state.project):1);if(j.min>j.max)throw Error(t('Minimum angle must be below maximum.','最小角度必须小于最大角度。'));j.angle=Math.max(j.min,Math.min(j.max,j.angle));},t('Adjust connection','调整连接'));}}catch(error){state.error=error.message;render();}});
root.addEventListener('submit',event=>{event.preventDefault();if(state.proposal)return;if(event.target.id==='create-form'){state.project={...state.project,brief:{...state.project.brief,keywords:state.prompt}};sessionChanged();aiRequest(state.capabilities?.imageGeneration?'generate-image':'create');}if(event.target.id==='refine-form')aiRequest('refine');});
function releaseDragCapture(d){try{d?.capture?.releasePointerCapture?.(d.pointerId);}catch{}}
function cancelDrag(){if(!drag)return;const d=drag;drag=null;releaseDragCapture(d);if(d.kind==='pan')state.camera=d.camera;suppressCanvasClick=d.moved;render();if(d.kind==='vertex')focusVertex(d.index);}
root.addEventListener('pointerdown',event=>{if(!drag)suppressCanvasClick=false;if(drag||event.isPrimary===false||(event.button!==undefined&&event.button!==0))return;const el=event.target.closest?.('[data-vertex-index]'),inCanvas=event.target.closest?.('#puppet-canvas')||event.target.closest?.('#canvas-wrap');if(state.mode!=='pan'&&(!el||state.mode!=='vertices'||!selected()||selected().locked))return;if(state.mode==='pan'&&!inCanvas)return;const start=screenPoint(event);if(!start)return;event.preventDefault?.();suppressCanvasClick=false;const capture=document.querySelector('#canvas-wrap');drag={kind:state.mode==='pan'?'pan':'vertex',partId:state.selected,index:el?Number(el.dataset.vertexIndex):null,start,clientX:event.clientX,clientY:event.clientY,camera:{...state.camera},unit:canvasUnits(),point:null,moved:false,pointerId:event.pointerId,capture};if(drag.kind==='vertex'){state.vertexIndex=drag.index;drag.vertexStart=transformPoint(partTransforms(state.project)[drag.partId],selected().polygon[drag.index]);el.focus?.();}try{capture?.setPointerCapture?.(event.pointerId);}catch{}});
document.addEventListener('pointermove',event=>{if(!drag||(drag.pointerId!==undefined&&event.pointerId!==undefined&&event.pointerId!==drag.pointerId))return;const dx=event.clientX-drag.clientX,dy=event.clientY-drag.clientY;if(!Number.isFinite(dx)||!Number.isFinite(dy)||(!drag.moved&&Math.hypot(dx,dy)<2))return;event.preventDefault?.();drag.moved=true;if(drag.kind==='pan'){state.camera=panCamera(drag.camera,-dx*drag.unit,-dy*drag.unit);redrawCanvas();return;}const point=screenPoint(event);if(!point)return;drag.point=localPoint(drag.partId,[drag.vertexStart[0]+point[0]-drag.start[0],drag.vertexStart[1]+point[1]-drag.start[1]]);const handle=document.querySelector(`[data-vertex-index="${drag.index}"]`);handle?.setAttribute?.('transform',`translate(${point[0]-drag.start[0]} ${point[1]-drag.start[1]})`);});
document.addEventListener('pointerup',event=>{if(!drag||(drag.pointerId!==undefined&&event?.pointerId!==undefined&&event.pointerId!==drag.pointerId))return;const d=drag;drag=null;releaseDragCapture(d);suppressCanvasClick=d.moved;if(d.kind==='pan'){render();return;}if(d.moved&&d.point){try{mutate(p=>{p.parts.find(p=>p.id===d.partId).polygon[d.index]=d.point;},t('Edit outline','编辑轮廓'));}catch(error){state.error=error.message;render();}}focusVertex(d.index);});
document.addEventListener('pointercancel',event=>{if(drag&&(drag.pointerId===undefined||event?.pointerId===undefined||event.pointerId===drag.pointerId))cancelDrag();});
document.addEventListener('keydown',event=>{const tag=event.target.tagName||'',vertex=event.target.closest?.('[data-vertex-index]');if(vertex&&state.mode==='vertices'&&selected()&&!selected().locked&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();const index=Number(vertex.dataset.vertexIndex),part=selected(),point=part?.polygon[index];if(!point)return;const world=transformPoint(partTransforms(state.project)[part.id],point),distance=canvasUnits()*(event.shiftKey?10:1),delta={ArrowLeft:[-distance,0],ArrowRight:[distance,0],ArrowUp:[0,-distance],ArrowDown:[0,distance]}[event.key],next=localPoint(part.id,[world[0]+delta[0],world[1]+delta[1]]);try{mutate(p=>{p.parts.find(p=>p.id===part.id).polygon[index]=next;},t('Move outline point','移动轮廓点'));}catch(error){state.error=error.message;render();}state.vertexIndex=index;focusVertex(index);return;}if(['Enter',' ','Spacebar'].includes(event.key)&&! /INPUT|TEXTAREA|SELECT|BUTTON/.test(tag)){const jointNode=event.target.closest?.('[data-joint-id]'),partNode=event.target.closest?.('[data-part-id]');const jointId=jointNode?.dataset.jointId,partId=jointId?state.project.joints.find(j=>j.id===jointId)?.childId:partNode?.dataset.partId;if(partId){event.preventDefault();choosePart(partId);root.querySelector(jointId?`[data-joint-id="${jointId}"]`:`[data-part-id="${partId}"]`)?.focus?.();return;}}if(event.key==='Escape'){const settings=state.settings;controller?.abort();cancelDrag();resetTool();state.settings=false;render();if(settings)document.querySelector('#ai-status-button')?.focus?.();}if(event.key==='Enter'&&state.mode==='draw'&&!/INPUT|TEXTAREA|SELECT/.test(tag)){event.preventDefault();root.querySelector('[data-action="finish-part"]')?.click();}});
window.addEventListener('resize',()=>{if(!drag&&!state.proposal)redrawCanvas();});
document.querySelector('#project-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;const epoch=sessionEpoch,version=state.version;try{if(file.size>55*1024*1024)throw Error('Project file is too large.');const project=parseStudioProject(await file.text());if(epoch!==sessionEpoch)return;if(version!==state.version)throw Error(t('The project changed during import. Open the file again.','导入期间项目已更改，请重新打开文件。'));commit(project,t('Open project','打开项目'));state.prompt=project.brief.keywords;state.step=project.parts.length||project.assets.length?'refine':'create';state.refineStage=project.parts.length?'pieces':'clean';state.camera={zoom:1,x:0,y:0};resetTool();render();}catch(error){if(epoch===sessionEpoch){state.error=error.message;render();}}finally{event.target.value='';}});
document.querySelector('#artwork-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;const epoch=sessionEpoch,version=state.version;try{const asset=await readArtworkFile(file);if(epoch!==sessionEpoch)return;if(version!==state.version)throw Error(t('The project changed during import. Choose the image again.','导入期间项目已更改，请重新选择图片。'));mutate(p=>{p.assets.push(asset);p.conceptAssetId=asset.id;p.canvas={width:asset.width,height:asset.height};},t('Import artwork','导入作品'));resetTool();state.selected=null;state.connectParent='';state.showArt=true;state.showConcept=true;state.step='refine';state.refineStage='clean';state.camera={zoom:1,x:0,y:0};render();toast(t('Use Image to pieces to remove the background or select an outline. You can also draw a custom part.','使用图像转部件工具去除背景或选取轮廓，也可以绘制自定义部件。'));}catch(error){if(epoch===sessionEpoch){state.error=error.message;render();}}finally{event.target.value='';}});

